#include <vector>

class Solution {
public:
    int minOrAfterOperations(std::vector<int>& nums, int k) {
        int ans = 0;
        int rans = 0;
        for (int i = 29; i >= 0; --i) {
            int test = ans + (1 << i);
            int cnt = 0;
            int val = 0;
            for (int num : nums) {
                if (val == 0) val = test & num;
                else val &= test & num;
                if (val != 0) cnt++;
            }
            if (cnt > k) rans += (1 << i);
            else ans += (1 << i);
        }
        return rans;
    }
};

