var minOrAfterOperations = function(nums, k) {
    let ans = 0;
    let rans = 0;
    for (let i = 29; i >= 0; --i) {
        const test = ans + (1 << i);
        let cnt = 0;
        let val = 0;
        for (const num of nums) {
            if (val === 0) val = test & num;
            else val &= test & num;
            if (val !== 0) cnt++;
        }
        if (cnt > k) rans += (1 << i);
        else ans += (1 << i);
    }
    return rans;
};
